# Name-filtering failed for these processes, so identify images by content: every contiguous
# MEM_IMAGE allocation starting with "MZ". No thread suspension (anti-dump safe).
$desk = "$env:USERPROFILE\Desktop"
$log = "$desk\dumpimg2-status.log"
function L($m) { Add-Content -Path $log -Value ("[{0:HH:mm:ss}] {1}" -f (Get-Date -Format 'HH:mm:ss'), $m) }
Set-Content -Path $log -Value ""

$cs = @'
using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;

public static class ImgDump2 {
  [DllImport("kernel32.dll", SetLastError = true)] public static extern IntPtr OpenProcess(uint a, bool i, int pid);
  [DllImport("kernel32.dll", SetLastError = true)] public static extern bool CloseHandle(IntPtr h);
  [DllImport("kernel32.dll", SetLastError = true)] public static extern IntPtr VirtualQueryEx(IntPtr h, IntPtr addr, out MEMORY_BASIC_INFORMATION mbi, uint len);
  [DllImport("kernel32.dll", SetLastError = true)] public static extern bool ReadProcessMemory(IntPtr h, IntPtr addr, byte[] b, uint sz, out IntPtr rd);

  [StructLayout(LayoutKind.Sequential)]
  public struct MEMORY_BASIC_INFORMATION {
    public IntPtr BaseAddress;
    public IntPtr AllocationBase;
    public uint AllocationProtect;
    public IntPtr RegionSize;
    public uint State;
    public uint Protect;
    public uint Type;
  }

  public static int DumpAllImages(IntPtr h, string outDir, string prefix, long maxPerImage) {
    long addr = 0x10000;
    int dumped = 0;
    var seen = new HashSet<long>();
    while (true) {
      MEMORY_BASIC_INFORMATION mbi;
      if (VirtualQueryEx(h, (IntPtr)addr, out mbi, (uint)Marshal.SizeOf(typeof(MEMORY_BASIC_INFORMATION))) == IntPtr.Zero) break;
      long size = mbi.RegionSize.ToInt64();
      if (size <= 0) break;
      long base_ = mbi.AllocationBase.ToInt64();
      if (mbi.Type == 0x1000000 && !seen.Contains(base_)) {   // MEM_IMAGE allocation group
        seen.Add(base_);
        // read first 2 bytes to check MZ
        byte[] head = new byte[2];
        IntPtr rd;
        if (ReadProcessMemory(h, mbi.AllocationBase, head, 2, out rd) && rd.ToInt64() == 2 && head[0] == 0x4D && head[1] == 0x5A) {
          string path = Path.Combine(outDir, prefix + "-img-" + base_.ToString("x") + ".bin");
          long written = 0;
          long cur = base_;
          using (FileStream fs = new FileStream(path, FileMode.Create, FileAccess.Write)) {
            while (cur < base_ + (long)0x40000000) {  // walk the allocation group (max 1GB guard)
              MEMORY_BASIC_INFORMATION m2;
              if (VirtualQueryEx(h, (IntPtr)cur, out m2, (uint)Marshal.SizeOf(typeof(MEMORY_BASIC_INFORMATION))) == IntPtr.Zero) break;
              long sz = m2.RegionSize.ToInt64();
              if (sz <= 0) break;
              if (m2.AllocationBase != mbi.AllocationBase) break;   // left the group
              if (m2.State == 0x1000 && m2.Protect != 0x01) {
                byte[] buf = new byte[sz];
                if (ReadProcessMemory(h, (IntPtr)cur, buf, (uint)sz, out rd)) {
                  fs.Write(buf, 0, (int)rd); written += (long)rd;
                }
              } else {
                fs.Write(new byte[sz], 0, (int)sz); written += sz;
              }
